import{_ as i,l as o,o as e,c as l,v as t,p as n,x as s,d,i as f,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Y-fast trie","description":"","frontmatter":{"title":"Y-fast trie","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/y-fast-trie.md","filePath":"cs/y-fast-trie.md","lastUpdated":1789023840000}'),h={name:"cs/y-fast-trie.md"};function c(m,a,E,_,g,B){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="y-fast-trie" tabindex="-1">Y-fast trie <a class="header-anchor" href="#y-fast-trie" aria-label="Permalink to &quot;Y-fast trie&quot;">​</a></h1><div class="epigraph"><p>x-fast 用分层哈希存前缀；y-fast 把键分成 $\\Theta(\\log U)$ 大小的块，块代表进 x-fast，块内平衡树，空间回到 $O(n)$。</p><footer>—— 据 Willard, Log-Logarithmic Worst-Case Range Queries are Possible in Space $\\Theta(N)$, IPL 1983；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/van-emde-boas">上一课</a> 的 \\(O(\\log\\log U)\\) 漂亮，朴素空间随 \\(U\\) 涨。本课不重写 summary 簇。缺口是 Willard 的 y-fast trie：先理解 x-fast（每层前缀哈希 + 叶链表），再把连续 \\(\\Theta(w)\\) 个键收成代表，使哈希表项 \\(O(n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x-fast trie：对每个已插入键的全部比特前缀建哈希，层 \\(i\\) 查 \\(x\\) 的 \\(i\\) 位前缀是否存在，二分深度得最长匹配，再跳到后继叶。时间 \\(O(\\log w)=O(\\log\\log U)\\)，空间 \\(O(n\\log U)\\)（每键 \\(w\\) 个前缀）。y-fast：叶层不存全部键，而存每块的最大（或代表）键，块内 BST 大小 \\(\\Theta(w)\\)。缺口是<strong>用一块代表换掉每键每层前缀</strong>，空间 \\(O(n)\\)，时间仍 \\(O(\\log\\log U)\\) 期望或最坏视哈希而定。</p><p><span class="marginnote">Willard 1983, <em>Information Processing Letters</em>。哈希用动态完美或通用散列时，界随哈希合同走；本课不提前写下两课散列族。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找后继：在 x-fast 上找代表后继，再在相邻一两块的 BST 里比。插入删除：块过大则裂，过小则并，像 B 树但块大小跟 \\(w\\) 走。代表变则更新 x-fast 前缀。</p>',8)),(e(),n(p,null,{default:s(()=>[f(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEYS%5B%22n%20%E4%B8%AA%E6%95%B4%E6%95%B0%E9%94%AE%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%E5%A4%A7%E5%B0%8F%20%CE%98(w)%22%5D%0A%20%20BLK%20--%3E%20XF%5B%22%E4%BB%A3%E8%A1%A8%E9%94%AE%E7%9A%84%20x-fast%22%5D%0A%20%20BLK%20--%3E%20BST%5B%22%E5%9D%97%E5%86%85%E6%9C%89%E5%BA%8F%E6%A0%91%22%5D%0A%20%20XF%20--%3E%20SUCC%5B%22O(log%20log%20U)%20%E6%89%BE%E5%88%B0%E5%9D%97%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 vEB：y-fast 空间优；常数与哈希失败概率要写进合同。与平衡 BST：当 \\(n\\ll U\\) 且 \\(w\\) 固定，y-fast 渐近更好，实践常数常输给 <a href="/cs/treap">Treap</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最长前缀匹配是比特 trie 的标准动作；哈希让「这一层有没有这个前缀」变期望 \\(O(1)\\)。块裂并摊还 \\(O(\\log\\log U)\\) 量级，分析类似 B 树加 x-fast 更新。</p><p>不要把本课写成 IP 路由硬件——那是最长前缀的应用，机制已够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入融合树。几何区间 stabbing 不是整数后继：下一课区间树，键是线段端点。</p><p>后课默认：整数宇宙后继可用 y-fast 换空间。轴对齐区间的stabbing 用区间树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>x-fast：\\(O(n w)\\) 空间，\\(O(\\log\\log U)\\) 后继。</li><li>y-fast：分块代表，空间 \\(O(n)\\)。</li><li>下一课从一维整数换到区间几何。</li><li>出处：Willard, <em>IPL</em>, 1983；Cormen et al.。</li></ul>',9))])}const A=i(h,[["render",c]]);export{u as __pageData,A as default};
